import assert from 'node:assert/strict';
const root=process.env.TEST_TALLER_URL||'http://127.0.0.1:4173';
const sessionCookie=process.env.SALVACEL_TEST_SESSION_COOKIE||'';
const nativeFetch=globalThis.fetch.bind(globalThis);
if(sessionCookie){globalThis.fetch=(input,init={})=>nativeFetch(input,{...init,headers:{Cookie:sessionCookie,...(init.headers||{})}});}
let checks=0;
const check=(value,message)=>{assert.ok(value,message);checks++;};
async function boot(){const r=await fetch(root+'/api/taller',{headers:sessionCookie?{Cookie:sessionCookie}:{}});assert.equal(r.status,200);return r.json();}
async function post(p,expected=200,headers={}){for(let attempt=0;attempt<3;attempt++){const r=await fetch(root+'/api/taller',{method:'POST',headers:{'Content-Type':'application/json',...(sessionCookie?{Cookie:sessionCookie}:{}),...headers},body:JSON.stringify(p)});const raw=await r.text();let d;try{d=JSON.parse(raw);}catch(error){if(raw.includes('worker restarted')&&attempt<2){await new Promise(resolve=>setTimeout(resolve,250));continue;}throw error;}assert.equal(r.status,expected,JSON.stringify(d));checks++;return d;}throw new Error('No se pudo completar la solicitud después de reintentar.');}
async function agentPost(p,expected=200,token=process.env.SALVACEL_AGENT_INGRESS_TOKEN){const response=await fetch(root+'/api/agent/supplier-messages',{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})},body:JSON.stringify(p)});const body=await response.json();assert.equal(response.status,expected,JSON.stringify(body));checks++;return body;}
const key=()=>crypto.randomUUID();
async function authPost(path,payload,cookie,expected){const response=await nativeFetch(root+path,{method:'POST',headers:{'Content-Type':'application/json',...(cookie?{Cookie:cookie}:{})},body:JSON.stringify(payload)});const body=await response.json();assert.equal(response.status,expected,JSON.stringify(body));checks++;return {response,body};}
